class Span:
    def __init__(self,b,p,end,row): self.b=b; self.p=p; self.end=end; self.row=row
    def fail(self,at,site,kind,**kw):
        raise Check(dict(row=self.row,absolute=at,site=site,kind=kind,raw=self.b[at:at+8].hex(),**kw))
    def take(self,w,s):
